SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, FIRST_VALUE(humidity) IGNORE NULLS OVER (ORDER BY pressure ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_humidity, LAST_VALUE(temp_c, TRUE) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_temp_c, ROW_NUMBER() OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) event_seq FROM device_readings;
